const { kRequestOrigin } = require('../../../lib/core/symbols')

describe('getRequestOrigin', () => {
  test('returns a string origin as-is', () => {
    expect(getRequestOrigin({ origin: 'http://example.com' })).toBe('http://example.com')
  })

  test('returns a URL origin unchanged', () => {
    const origin = new URL('https://example.com:8443/base')
    expect(getRequestOrigin({ origin })).toBe(origin)
  })

  test('returns null when origin is missing', () => {
    expect(getRequestOrigin({})).toBeNull()
  })

  test('returns null when origin is not a string or URL', () => {
    expect(getRequestOrigin({ origin: 42 })).toBeNull()
    expect(getRequestOrigin({ origin: { href: 'http://example.com' } })).toBeNull()
    expect(getRequestOrigin({ origin: null })).toBeNull()
  })

  test('prefers the internal request origin symbol over opts.origin', () => {
    const opts = {
      origin: 'http://original.example',
      [kRequestOrigin]: 'http://resolved.example'
    }
    expect(getRequestOrigin(opts)).toBe('http://resolved.example')
  })

  test('falls back to opts.origin when the symbol is undefined', () => {
    const opts = { origin: 'http://original.example', [kRequestOrigin]: undefined }
    expect(getRequestOrigin(opts)).toBe('http://original.example')
  })
})

describe('getInterceptorOrigin', () => {
  test('returns the request origin when no interceptor origin is configured', () => {
    expect(getInterceptorOrigin({ origin: 'http://example.com' }, undefined)).toBe('http://example.com')
  })

  test('returns null when the interceptor is explicitly restricted to null', () => {
    expect(getInterceptorOrigin({ origin: 'http://example.com' }, null)).toBeNull()
  })

  test('returns the interceptor origin when the request has no usable origin', () => {
    expect(getInterceptorOrigin({}, 'http://interceptor.example')).toBe('http://interceptor.example')
    expect(getInterceptorOrigin({ origin: 17 }, 'http://interceptor.example')).toBe('http://interceptor.example')
  })

  test('returns the interceptor origin when request and interceptor origins match', () => {
    expect(getInterceptorOrigin({ origin: 'http://example.com' }, 'http://example.com')).toBe('http://example.com')
    expect(getInterceptorOrigin({ origin: new URL('http://example.com/path?q=1') }, 'http://example.com'))
      .toBe('http://example.com')
  })

  test('returns null when request and interceptor origins differ', () => {
    expect(getInterceptorOrigin({ origin: 'http://example.com' }, 'http://other.example')).toBeNull()
    expect(getInterceptorOrigin({ origin: 'https://example.com' }, 'http://example.com')).toBeNull()
  })

  test('returns the interceptor origin when the request origin cannot be parsed as a URL', () => {
    expect(getInterceptorOrigin({ origin: 'not a url' }, 'http://interceptor.example'))
      .toBe('http://interceptor.example')
  })

  test('compares against the resolved internal request origin', () => {
    const opts = {
      origin: 'http://a.example',
      [kRequestOrigin]: 'http://b.example'
    }
    expect(getInterceptorOrigin(opts, 'http://a.example')).toBeNull()
    expect(getInterceptorOrigin(opts, 'http://b.example')).toBe('http://b.example')
  })
})

describe('makeCacheKey', () => {
  test('builds a key with a default path of /', () => {
    expect(makeCacheKey({ origin: 'http://example.com', method: 'GET' })).toEqual({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers: undefined
    })
  })

  test('stringifies URL origins and keeps headers', () => {
    const headers = { accept: 'text/plain' }
    expect(makeCacheKey({
      origin: new URL('http://example.com:8080/base'),
      method: 'HEAD',
      path: '/resource',
      headers
    })).toEqual({
      origin: 'http://example.com:8080/base',
      method: 'HEAD',
      path: '/resource',
      headers
    })
  })

  test('appends serialized query parameters when the path has none', () => {
    expect(makeCacheKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/search',
      query: { b: '2', a: '1' }
    }).path).toBe('/search?b=2&a=1')
  })

  test('serializes repeated query parameter values', () => {
    expect(makeCacheKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/search',
      query: { a: ['1', '2'] }
    }).path).toBe('/search?a=1&a=2')
  })

  test('leaves the path untouched when query is empty', () => {
    expect(makeCacheKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/search',
      query: {}
    }).path).toBe('/search')
  })

  test('leaves paths that already contain a query string untouched', () => {
    expect(makeCacheKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/search?q=1',
      query: { a: '2' }
    }).path).toBe('/search?q=1')
  })

  test('leaves paths that already contain a fragment untouched', () => {
    expect(makeCacheKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/search#frag',
      query: { a: '2' }
    }).path).toBe('/search#frag')
  })

  test('throws when no origin can be determined', () => {
    expect(() => makeCacheKey({ method: 'GET' })).toThrow('opts.origin is undefined')
    expect(() => makeCacheKey({ method: 'GET' }, null)).toThrow('opts.origin is undefined')
  })

  test('uses an explicitly provided origin', () => {
    expect(makeCacheKey({ origin: 'http://ignored.example', method: 'GET' }, 'http://explicit.example').origin)
      .toBe('http://explicit.example')
  })
})

describe('normalizeHeaders', () => {
  test('returns an empty object when headers are missing', () => {
    expect(normalizeHeaders({})).toEqual({})
    expect(normalizeHeaders({ headers: null })).toEqual({})
    expect(normalizeHeaders({ headers: undefined })).toEqual({})
  })

  test('lowercases header names from a plain object', () => {
    expect(normalizeHeaders({ headers: { 'Content-Type': 'text/plain', 'X-Custom': 'v' } }))
      .toEqual({ 'content-type': 'text/plain', 'x-custom': 'v' })
  })

  test('copies array header values so the input is not aliased', () => {
    const input = { 'x-custom': ['a', 'b'] }
    const result = normalizeHeaders({ headers: input })
    expect(result['x-custom']).toEqual(['a', 'b'])
    expect(result['x-custom']).not.toBe(input['x-custom'])
  })

  test('combines duplicate names that differ only by case', () => {
    expect(normalizeHeaders({ headers: { 'X-Custom': 'a', 'x-custom': 'b' } }))
      .toEqual({ 'x-custom': ['a', 'b'] })
  })

  test('accepts a Map of headers and merges duplicates', () => {
    expect(normalizeHeaders({ headers: new Map([['A', '1'], ['a', '2']]) })).toEqual({ a: ['1', '2'] })
  })

  test('accepts an array of [name, value] pairs', () => {
    expect(normalizeHeaders({ headers: [['A', '1'], ['B', '2']] })).toEqual({ a: '1', b: '2' })
    expect(normalizeHeaders({ headers: [['A', '1'], ['a', '2']] })).toEqual({ a: ['1', '2'] })
  })

  test('accepts a flat alternating array and merges duplicates', () => {
    expect(normalizeHeaders({ headers: ['a', '1', 'b', '2'] })).toEqual({ a: '1', b: '2' })
    expect(normalizeHeaders({ headers: ['a', '1', 'A', '2'] })).toEqual({ a: ['1', '2'] })
  })

  test('expands array values in a flat alternating array', () => {
    expect(normalizeHeaders({ headers: ['a', ['1', '2']] })).toEqual({ a: ['1', '2'] })
  })

  test('converts Buffer values in a flat alternating array using latin1', () => {
    expect(normalizeHeaders({ headers: ['a', [Buffer.from('héllo', 'latin1'), 'plain']] }))
      .toEqual({ a: ['héllo', 'plain'] })
  })

  test('rejects non-object headers', () => {
    expect(() => normalizeHeaders({ headers: 'a=b' })).toThrow('opts.headers is not an object')
    expect(() => normalizeHeaders({ headers: 42 })).toThrow('opts.headers is not an object')
  })

  test('rejects a flat alternating array with an odd number of entries', () => {
    expect(() => normalizeHeaders({ headers: ['a', '1', 'b'] }))
      .toThrow('opts.headers is not a valid header map')
  })

  test('rejects non-string names and values in an array of pairs', () => {
    expect(() => normalizeHeaders({ headers: [['a', 1]] }))
      .toThrow('opts.headers is not a valid header map')
    expect(() => normalizeHeaders({ headers: [[1, 'a']] }))
      .toThrow('opts.headers is not a valid header map')
  })

  test('rejects mixed entry shapes in an array of pairs', () => {
    expect(() => normalizeHeaders({ headers: [['a', '1'], 'b'] }))
      .toThrow('opts.headers is not a valid header map')
  })

  test('does not pollute the prototype through a __proto__ header name', () => {
    const input = JSON.parse('{"__proto__":"evil","a":"1"}')
    const result = normalizeHeaders({ headers: input })

    expect(Object.hasOwn(result, '__proto__')).toBe(true)
    expect(Object.getOwnPropertyDescriptor(result, '__proto__').value).toBe('evil')
    expect(Object.getPrototypeOf(result)).toBe(Object.prototype)
    expect(({}).evil).toBeUndefined()
  })
})

