describe('parseCacheControlHeader', () => {
  test('parses a single numeric directive', () => {
    expect(parseCacheControlHeader('max-age=60')).toEqual({ 'max-age': 60 })
  })

  test('parses every supported numeric directive', () => {
    expect(parseCacheControlHeader('s-maxage=30')).toEqual({ 's-maxage': 30 })
    expect(parseCacheControlHeader('min-fresh=5')).toEqual({ 'min-fresh': 5 })
    expect(parseCacheControlHeader('max-stale=15')).toEqual({ 'max-stale': 15 })
    expect(parseCacheControlHeader('stale-while-revalidate=7')).toEqual({ 'stale-while-revalidate': 7 })
    expect(parseCacheControlHeader('stale-if-error=9')).toEqual({ 'stale-if-error': 9 })
  })

  test('parses boolean directives', () => {
    expect(parseCacheControlHeader('no-store')).toEqual({ 'no-store': true })
    expect(parseCacheControlHeader('no-cache')).toEqual({ 'no-cache': true })
    expect(parseCacheControlHeader('private')).toEqual({ private: true })
    expect(parseCacheControlHeader('public')).toEqual({ public: true })
    expect(parseCacheControlHeader('must-revalidate')).toEqual({ 'must-revalidate': true })
    expect(parseCacheControlHeader('proxy-revalidate')).toEqual({ 'proxy-revalidate': true })
    expect(parseCacheControlHeader('immutable')).toEqual({ immutable: true })
    expect(parseCacheControlHeader('no-transform')).toEqual({ 'no-transform': true })
    expect(parseCacheControlHeader('must-understand')).toEqual({ 'must-understand': true })
    expect(parseCacheControlHeader('only-if-cached')).toEqual({ 'only-if-cached': true })
  })

  test('parses multiple directives and is case insensitive', () => {
    expect(parseCacheControlHeader('Max-Age=60, NO-STORE, Public')).toEqual({
      'max-age': 60,
      'no-store': true,
      public: true
    })
  })

  test('accepts an array of header lines', () => {
    expect(parseCacheControlHeader(['max-age=60', 'no-store'])).toEqual({ 'max-age': 60, 'no-store': true })
    expect(parseCacheControlHeader(['max-age=60, no-store'])).toEqual({ 'max-age': 60, 'no-store': true })
  })

  test('keeps the most restrictive max-age', () => {
    expect(parseCacheControlHeader('max-age=100, max-age=50')).toEqual({ 'max-age': 50 })
    expect(parseCacheControlHeader('max-age=50, max-age=100')).toEqual({ 'max-age': 50 })
  })

  test('keeps the largest min-fresh', () => {
    expect(parseCacheControlHeader('min-fresh=10, min-fresh=50')).toEqual({ 'min-fresh': 50 })
    expect(parseCacheControlHeader('min-fresh=50, min-fresh=10')).toEqual({ 'min-fresh': 50 })
  })

  test('accepts quoted numeric values', () => {
    expect(parseCacheControlHeader('max-age="60"')).toEqual({ 'max-age': 60 })
  })

  test('clamps delta seconds to the maximum 32 bit integer', () => {
    expect(parseCacheControlHeader('max-age=2147483648')).toEqual({ 'max-age': 2147483647 })
    expect(parseCacheControlHeader('max-age=99999999999999999999')).toEqual({ 'max-age': 2147483647 })
  })

  test('marks invalid numeric directives as invalid and drops them', () => {
    const directives = parseCacheControlHeader('max-age=abc')
    expect(directives).toEqual({})
    expect(hasInvalidCacheControlDirective(directives, 'max-age')).toBe(true)
  })

  test('rejects non-integer numeric values', () => {
    const directives = parseCacheControlHeader('max-age=1.5')
    expect(directives).toEqual({})
    expect(hasInvalidCacheControlDirective(directives, 'max-age')).toBe(true)
  })

  test('drops numeric directives without a value', () => {
    const directives = parseCacheControlHeader('max-age')
    expect(directives).toEqual({})
    expect(hasInvalidCacheControlDirective(directives, 'max-age')).toBe(true)
  })

  test('a malformed later directive invalidates the previously parsed value', () => {
    const directives = parseCacheControlHeader('max-age=60, max-age= 30')
    expect(directives).toEqual({})
    expect(hasInvalidCacheControlDirective(directives, 'max-age')).toBe(true)
  })

  test('keeps valid directives when an unrelated directive is invalid', () => {
    const directives = parseCacheControlHeader('no-store, s-maxage=oops')
    expect(directives).toEqual({ 'no-store': true })
    expect(hasInvalidCacheControlDirective(directives, 's-maxage')).toBe(true)
    expect(hasInvalidCacheControlDirective(directives, 'no-store')).toBe(false)
  })

  test('parses a qualified no-cache field list from a quoted list', () => {
    expect(parseCacheControlHeader('no-cache="set-cookie, authorization"')).toEqual({
      'no-cache': ['set-cookie', 'authorization']
    })
  })

  test('parses a qualified no-cache with unquoted and quoted single fields', () => {
    expect(parseCacheControlHeader('no-cache=set-cookie')).toEqual({ 'no-cache': ['set-cookie'] })
    expect(parseCacheControlHeader('no-cache="set-cookie"')).toEqual({ 'no-cache': ['set-cookie'] })
  })

  test('accumulates repeated qualified no-cache directives', () => {
    expect(parseCacheControlHeader('no-cache=foo, no-cache=bar')).toEqual({ 'no-cache': ['foo', 'bar'] })
    expect(parseCacheControlHeader('no-cache="a", no-cache="b"')).toEqual({ 'no-cache': ['a', 'b'] })
  })

  test('degrades qualified directives with invalid field names to true', () => {
    expect(parseCacheControlHeader('no-cache=bad@name')).toEqual({ 'no-cache': true })
    expect(parseCacheControlHeader('no-cache="a b"')).toEqual({ 'no-cache': true })
  })

  test('treats an empty no-cache value as unqualified', () => {
    expect(parseCacheControlHeader('no-cache=')).toEqual({ 'no-cache': true })
    expect(parseCacheControlHeader('no-cache=""')).toEqual({ 'no-cache': true })
  })

  test('parses qualified private directives like no-cache', () => {
    expect(parseCacheControlHeader('private=x')).toEqual({ private: ['x'] })
    expect(parseCacheControlHeader('private="a, b", no-store')).toEqual({
      private: ['a', 'b'],
      'no-store': true
    })
  })

  test('handles a qualified directive combined with other directives', () => {
    expect(parseCacheControlHeader('max-age=60, no-cache="set-cookie"')).toEqual({
      'max-age': 60,
      'no-cache': ['set-cookie']
    })
  })

  test('degrades an unterminated quoted field list to true', () => {
    expect(parseCacheControlHeader('no-cache="a')).toEqual({ 'no-cache': true })
    expect(parseCacheControlHeader('no-cache="foo, max-age=10')).toEqual({ 'no-cache': true })
  })

  test('ignores numeric directives hidden inside a malformed quoted value', () => {
    expect(parseCacheControlHeader('public="x, max-age=60')).toEqual({})
  })

  test('ignores unknown directives', () => {
    expect(parseCacheControlHeader('foo=bar, unknown')).toEqual({})
  })

  test('returns an empty set for empty headers', () => {
    expect(parseCacheControlHeader('')).toEqual({})
    expect(parseCacheControlHeader('   ')).toEqual({})
    expect(parseCacheControlHeader([])).toEqual({})
  })

  test('drops no-argument directives that are given a value for every occurrence', () => {
    expect(parseCacheControlHeader('public=x, public')).toEqual({})
    expect(parseCacheControlHeader('only-if-cached=x')).toEqual({})
    expect(parseCacheControlHeader('immutable="yes", immutable')).toEqual({})
  })

  test('keeps no-store even when other directives are malformed', () => {
    const directives = parseCacheControlHeader('max-age="60, no-store')
    expect(directives).toEqual({ 'no-store': true })
    expect(hasInvalidCacheControlDirective(directives, 'max-age')).toBe(true)
  })

  test('recognises restrictive directives with malformed token characters', () => {
    expect(parseCacheControlHeader('no-store@x')).toEqual({ 'no-store': true })
    expect(parseCacheControlHeader('no-cache;')).toEqual({ 'no-cache': true })
    expect(parseCacheControlHeader('private x')).toEqual({ private: true })
  })

  test('tolerates whitespace around directive names and values', () => {
    expect(parseCacheControlHeader('  max-age=60,  no-store  ')).toEqual({ 'max-age': 60, 'no-store': true })
  })

  test('treats quoted field names containing escapes or quotes as invalid', () => {
    expect(parseCacheControlHeader('no-cache="a\\"b", no-store')).toEqual({
      'no-cache': true,
      'no-store': true
    })
  })
})

describe('hasInvalidCacheControlDirective', () => {
  test('returns false for a directive set that had no invalid entries', () => {
    expect(hasInvalidCacheControlDirective(parseCacheControlHeader('max-age=60'), 'max-age')).toBe(false)
    expect(hasInvalidCacheControlDirective(parseCacheControlHeader('no-store'), 'max-age')).toBe(false)
  })

  test('returns false for a plain object that was never parsed', () => {
    expect(hasInvalidCacheControlDirective({}, 'max-age')).toBe(false)
  })

  test('returns true only for the directive that was invalid', () => {
    const directives = parseCacheControlHeader('max-age=x, min-fresh=10')
    expect(hasInvalidCacheControlDirective(directives, 'max-age')).toBe(true)
    expect(hasInvalidCacheControlDirective(directives, 'min-fresh')).toBe(false)
  })
})

describe('hasVaryStar', () => {
  test('detects a wildcard vary header', () => {
    expect(hasVaryStar('*')).toBe(true)
    expect(hasVaryStar('accept-encoding, *')).toBe(true)
    expect(hasVaryStar(' * ')).toBe(true)
  })

  test('detects a wildcard inside any value of an array header', () => {
    expect(hasVaryStar(['accept-encoding', '*'])).toBe(true)
    expect(hasVaryStar(['accept-encoding', 'x*y'])).toBe(true)
  })

  test('returns false when no wildcard is present', () => {
    expect(hasVaryStar('accept-encoding')).toBe(false)
    expect(hasVaryStar('accept-encoding, accept-language')).toBe(false)
    expect(hasVaryStar([])).toBe(false)
    expect(hasVaryStar('')).toBe(false)
  })
})

describe('parseVaryHeader', () => {
