    expect(parseVaryHeader('Accept-Encoding', { 'accept-encoding': 'gzip' })).toEqual({
      'accept-encoding': 'gzip'
    })
    expect(parseVaryHeader('accept-encoding, accept-language', {
      'accept-encoding': 'gzip',
      'accept-language': 'en'
    })).toEqual({ 'accept-encoding': 'gzip', 'accept-language': 'en' })
  })

  test('uses null for headers that are absent from the request', () => {
    expect(parseVaryHeader('accept-encoding, user-agent', { 'accept-encoding': 'gzip' })).toEqual({
      'accept-encoding': 'gzip',
      'user-agent': null
    })
  })

  test('copies array header values', () => {
    const headers = { 'accept-encoding': ['gzip', 'br'] }
    const result = parseVaryHeader('accept-encoding', headers)
    expect(result['accept-encoding']).toEqual(['gzip', 'br'])
    expect(result['accept-encoding']).not.toBe(headers['accept-encoding'])
  })

  test('returns the original headers object for a wildcard vary header', () => {
    const headers = { 'accept-encoding': 'gzip' }
    expect(parseVaryHeader('*', headers)).toBe(headers)
  })

  test('accepts an array of vary header lines', () => {
    expect(parseVaryHeader(['accept-encoding', 'accept-language'], {
      'accept-encoding': 'gzip',
      'accept-language': 'en'
    })).toEqual({ 'accept-encoding': 'gzip', 'accept-language': 'en' })
  })

  test('ignores empty entries', () => {
    expect(parseVaryHeader('', {})).toEqual({})
    expect(parseVaryHeader('accept-encoding,,', { 'accept-encoding': 'gzip' })).toEqual({
      'accept-encoding': 'gzip'
    })
  })

  test('returns undefined for invalid header names', () => {
    expect(parseVaryHeader('accept encoding', {})).toBeUndefined()
    expect(parseVaryHeader('accept-encoding, bad header', { 'accept-encoding': 'gzip' })).toBeUndefined()
  })
})

describe('isInvalidOrWildcardVaryHeader', () => {
