      .toThrow('CacheStore needs to have a `createWriteStream()` function')
    expect(() => assertCacheStore({ get () {}, createWriteStream () {} }))
      .toThrow('CacheStore needs to have a `delete()` function')
    expect(() => assertCacheStore({ get: 'nope', createWriteStream () {}, delete () {} }))
      .toThrow('CacheStore needs to have a `get()` function')
  })

