describe('makeDeduplicationKey', () => {
  test('produces a JSON encoded array of origin, method, path, and headers', () => {
    const key = makeDeduplicationKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/resource'
    })
    expect(JSON.parse(key)).toEqual(['http://example.com', 'GET', '/resource', {}])
  })

  test('produces the same key regardless of header insertion order', () => {
    const a = makeDeduplicationKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers: { b: '2', a: '1' }
    })
    const b = makeDeduplicationKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers: { a: '1', b: '2' }
    })
    expect(a).toBe(b)
  })

  test('distinguishes different origins, methods, paths, and header values', () => {
    const base = { origin: 'http://example.com', method: 'GET', path: '/', headers: { a: '1' } }
    expect(makeDeduplicationKey(base)).not.toBe(makeDeduplicationKey({ ...base, origin: 'http://other.example' }))
    expect(makeDeduplicationKey(base)).not.toBe(makeDeduplicationKey({ ...base, method: 'HEAD' }))
    expect(makeDeduplicationKey(base)).not.toBe(makeDeduplicationKey({ ...base, path: '/other' }))
    expect(makeDeduplicationKey(base)).not.toBe(makeDeduplicationKey({ ...base, headers: { a: '2' } }))
  })

  test('does not collide on header values containing delimiters', () => {
    const one = makeDeduplicationKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers: { a: 'x:b=y' }
    })
    const two = makeDeduplicationKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers: { a: 'x', b: 'y' }
    })
    expect(one).not.toBe(two)
  })

  test('preserves array header values', () => {
    const key = makeDeduplicationKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers: { a: ['1', '2'] }
    })
    expect(JSON.parse(key)[3]).toEqual({ a: ['1', '2'] })
  })

  test('omits excluded headers case-insensitively', () => {
    const key = makeDeduplicationKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers: { 'Accept-Encoding': 'gzip', a: '1' }
    }, new Set(['accept-encoding']))
    expect(JSON.parse(key)[3]).toEqual({ a: '1' })
  })

  test('does not alter the key when the exclusion set does not match', () => {
    const key = makeDeduplicationKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers: { a: '1' }
    }, new Set(['accept-encoding']))
    expect(JSON.parse(key)[3]).toEqual({ a: '1' })
  })

  test('handles a __proto__ header name without polluting the key object', () => {
    const headers = JSON.parse('{"__proto__":"evil","a":"1"}')
    const key = makeDeduplicationKey({
      origin: 'http://example.com',
      method: 'GET',
      path: '/',
      headers
    })
    const parsedHeaders = JSON.parse(key)[3]
    expect(Object.hasOwn(parsedHeaders, '__proto__')).toBe(true)
    expect(Object.getOwnPropertyDescriptor(parsedHeaders, '__proto__').value).toBe('evil')
    expect(parsedHeaders.a).toBe('1')
    expect(({}).evil).toBeUndefined()
  })
})

