        handler.controller.abort.mockImplementation(resolve)
      })

      parser.write(Buffer.concat([
        makeFrame({
          opcode: opcodes.TEXT,
          payload: parts[0],
          fin: false,
          rsv1: true
        }),
        makeFrame({
          opcode: opcodes.CONTINUATION,
          payload: parts[1]
        })
      ]))

      await aborted
      expect(handler.onMessage).not.toHaveBeenCalled()
      expectConnectionFailure(handler, 1009)
    })

    it('fails the connection when decompressed data exceeds maxPayloadSize', async () => {
      const { parser, handler } = createParser({
        extensions: new Map([['permessage-deflate', '']]),
        options: { maxPayloadSize: 50 }
      })
      const compressed = zlib.deflateRawSync(Buffer.alloc(1000, 0x61), {
        finishFlush: zlib.constants.Z_SYNC_FLUSH
