        payload: compressed,
        rsv1: true
      }))

      await aborted
      expect(handler.onMessage).not.toHaveBeenCalled()
      expectConnectionFailure(handler, 1009)
    })
  })

  describe('public parsing helpers', () => {
    it('returns an empty buffer for consume(0) and throws for an over-consumption', () => {
      const { parser } = createParser()

      const empty = parser.consume(0)
      expect(empty.length).toBe(0)
