'use strict'

/* global describe, it, expect, jest */

const { EventEmitter } = require('node:events')
const zlib = require('node:zlib')

const { ByteParser } = require('../../../../lib/web/websocket/receiver')
const { PerMessageDeflate } = require('../../../../lib/web/websocket/permessage-deflate')
const {
  opcodes,
  states,
  sentCloseFrameState
} = require('../../../../lib/web/websocket/constants')

function createSocket () {
  const socket = new EventEmitter()

  socket.writableNeedDrain = false
  socket.destroyed = false
  socket.writes = []
  socket.write = jest.fn((chunk) => {
    socket.writes.push(Buffer.from(chunk))
    return true
  })
  socket.destroy = jest.fn(() => {
    socket.destroyed = true
  })

  return socket
}

function createHandler (overrides = {}) {
  const socket = overrides.socket ?? createSocket()
  const handler = {
    onMessage: jest.fn(),
    onPing: jest.fn(),
    onPong: jest.fn(),
    readyState: states.OPEN,
    closeState: new Set(),
    controller: { abort: jest.fn() },
    onSocketClose: jest.fn(),
    ...overrides,
    socket
  }

  return handler
}

function createParser ({ handler: handlerOverrides, options, extensions = null } = {}) {
  const handler = createHandler(handlerOverrides)
  return {
    handler,
    socket: handler.socket,
    parser: new ByteParser(handler, extensions, options)
  }
}

function makeFrame ({
  opcode,
  payload = Buffer.alloc(0),
  fin = true,
  rsv1 = false,
  rsv2 = false,
  rsv3 = false,
  masked = false
}) {
  const body = Buffer.isBuffer(payload) ? payload : Buffer.from(payload)
  const firstByte = (fin ? 0x80 : 0) |
    (rsv1 ? 0x40 : 0) |
    (rsv2 ? 0x20 : 0) |
    (rsv3 ? 0x10 : 0) |
    opcode

  let secondByte = body.length
  let extendedLength = Buffer.alloc(0)

  if (body.length > 125 && body.length <= 0xffff) {
    secondByte = 126
    extendedLength = Buffer.allocUnsafe(2)
    extendedLength.writeUInt16BE(body.length, 0)
  } else if (body.length > 0xffff) {
    secondByte = 127
    extendedLength = Buffer.allocUnsafe(8)
    extendedLength.writeUInt32BE(0, 0)
    extendedLength.writeUInt32BE(body.length, 4)
  }

  if (masked) {
    secondByte |= 0x80
  }

  return Buffer.concat([
    Buffer.from([firstByte, secondByte]),
    extendedLength,
    body
  ])
}

function decodeFrame (frame) {
  expect(Buffer.isBuffer(frame)).toBe(true)

  const firstByte = frame[0]
  const secondByte = frame[1]
  const masked = (secondByte & 0x80) !== 0
  let payloadLength = secondByte & 0x7f
  let offset = 2

  if (payloadLength === 126) {
    payloadLength = frame.readUInt16BE(offset)
    offset += 2
  } else if (payloadLength === 127) {
    payloadLength = Number(frame.readBigUInt64BE(offset))
    offset += 8
  }

  let mask
  if (masked) {
    mask = frame.subarray(offset, offset + 4)
    offset += 4
  }

  const body = Buffer.from(frame.subarray(offset, offset + payloadLength))
  if (masked) {
    for (let i = 0; i < body.length; ++i) {
      body[i] ^= mask[i & 3]
    }
  }

  return {
    fin: (firstByte & 0x80) !== 0,
    opcode: firstByte & 0x0f,
    masked,
    body
  }
}

function expectConnectionFailure (handler, code) {
  expect(handler.controller.abort).toHaveBeenCalledTimes(1)
  expect(handler.socket.destroy).toHaveBeenCalledTimes(1)
  expect(handler.socket.destroyed).toBe(true)
  expect(handler.readyState).toBe(states.CLOSING)
  expect(handler.closeState.has(sentCloseFrameState.SENT)).toBe(true)

  const closeFrame = decodeFrame(handler.socket.writes.at(-1))
  expect(closeFrame.opcode).toBe(opcodes.CLOSE)
  expect(closeFrame.body.length).toBeGreaterThanOrEqual(2)
  expect(closeFrame.body.readUInt16BE(0)).toBe(code)
}

function closePayload (code, reason = Buffer.alloc(0)) {
  const reasonBuffer = Buffer.isBuffer(reason) ? reason : Buffer.from(reason)
  const body = Buffer.allocUnsafe(2 + reasonBuffer.length)
  body.writeUInt16BE(code, 0)
  reasonBuffer.copy(body, 2)
  return body
}

async function deflateParts (parts) {
  const deflater = zlib.createDeflateRaw()
  const groups = []
  let current = null

  deflater.on('data', (chunk) => {
    if (current) current.push(chunk)
  })

  for (const part of parts) {
    current = []
    await new Promise((resolve, reject) => {
      deflater.write(part, (error) => error ? reject(error) : resolve())
    })
    await new Promise((resolve, reject) => {
      deflater.flush(zlib.constants.Z_SYNC_FLUSH, (error) => error ? reject(error) : resolve())
    })
    groups.push(Buffer.concat(current))
    current = null
  }

  deflater.close()
  return groups
}

